from datetime import datetime

class Classroom:
    TIME_FORMAT = '%H:%M'

    def __init__(self, id):
        self.id = id
        self._courses = []

    @property
    def courses(self):
        return self._courses

    def _set_courses(self, courses):
        self._courses = courses

    def add_course(self, course):
        if course not in self._courses:
            self._courses.append(course)

    def remove_course(self, course):
        if course in self._courses:
            self._courses.remove(course)

    def _parse_time(self, time_str):
        return datetime.strptime(time_str, self.TIME_FORMAT)

    def _is_within_time_range(self, check_time, start_time, end_time):
        return start_time <= check_time <= end_time

    def is_free_at(self, check_time):
        check_time = self._parse_time(check_time)
        return all(
            not self._is_within_time_range(check_time, self._parse_time(course['start_time']), self._parse_time(course['end_time']))
            for course in self._courses
        )

    def _times_overlap(self, time1_start, time1_end, time2_start, time2_end):
        return time1_start <= time2_end and time2_start <= time1_end

    def check_course_conflict(self, new_course):
        new_start_time = self._parse_time(new_course['start_time'])
        new_end_time = self._parse_time(new_course['end_time'])
        return all(
            not self._times_overlap(
                self._parse_time(course['start_time']),
                self._parse_time(course['end_time']),
                new_start_time,
                new_end_time
            )
            for course in self._courses
        )
